/* Short external name for the shared DPMI allocation error state. */
unsigned int dpmi_dos_segment;
unsigned int dpmi_selector_or_failure_marker;
unsigned int dpmi_segment_linear_base;
/* TU allocate_dpmi_memory..query_largest_dos_free_block [0xdea6, 0xdfc3): generated by tools/tu.py */
#include <stdlib.h>
#include <i86.h>
#include <string.h>
#define DPMI_INTERRUPT 0x31
#define DPMI_ALLOCATE_DOS_MEMORY 0x0100
#define DPMI_FREE_DOS_MEMORY 0x0101
#define DOS_INTERRUPT 0x21
#define DOS_GET_LARGEST_FREE_BLOCK 0x48
/* Game-private allocation result, shared for a zero-size request and DPMI failure. */
#define DPMI_MEMORY_ALLOCATION_ERROR_CODE 0x504
#define DOS_PARAGRAPH_ROUNDUP_MASK 15
#define DOS_PARAGRAPH_SHIFT 4
extern int random_seed_low;
extern int random_seed_high;
extern unsigned int largest_dpmi_free_block_bytes;
extern int dos_memory_error;
extern void *heap_block;
void seed_random_generator(int a, int b);
int next_random_value(void);
int random_in_range(int minimum, int maximum);
void *alloc_heap_block(int byte_count);
void free_heap_block(void *p);
unsigned int query_largest_dpmi_free_block(void);
unsigned int allocate_dpmi_memory(int byte_count);
void free_dpmi_memory(unsigned int memory_handle);
unsigned int query_largest_dos_free_block(void);

/* _DATA [0x75c0,0x75c8) */
unsigned int largest_dos_free_block_bytes = 0;
/* Shared DPMI allocation status/error code. */
unsigned int dpmi_err = 0;

unsigned int allocate_dpmi_memory(int byte_count) {
    union REGS regs;
    /* DPMI 0100h allocates DOS memory in 16-byte paragraphs. */
    regs.w.ax = DPMI_ALLOCATE_DOS_MEMORY;
    regs.w.bx = (byte_count + DOS_PARAGRAPH_ROUNDUP_MASK) >> DOS_PARAGRAPH_SHIFT;
    int386(DPMI_INTERRUPT, &regs, &regs);
    if (regs.x.cflag != 0) {
        dpmi_selector_or_failure_marker = ((unsigned int)regs.w.bx << DOS_PARAGRAPH_SHIFT) | 1;
        dpmi_err = DPMI_MEMORY_ALLOCATION_ERROR_CODE;
        return 0;
    }
    if (byte_count == 0)
        dpmi_err = DPMI_MEMORY_ALLOCATION_ERROR_CODE;
    else
        dpmi_err = 0;
    /* DPMI 0100h returns the DOS segment in AX and its selector in DX. */
    dpmi_dos_segment = regs.w.ax;
    dpmi_selector_or_failure_marker = regs.w.dx;
    dpmi_segment_linear_base = dpmi_dos_segment << DOS_PARAGRAPH_SHIFT;
    return dpmi_segment_linear_base;
}

void free_dpmi_memory(unsigned int memory_selector) {
    union REGS regs;
    if (memory_selector != 0) {
        /* DPMI 0101h frees the allocation using its selector in DX. */
        regs.w.ax = DPMI_FREE_DOS_MEMORY;
        regs.w.dx = memory_selector;
        int386(DPMI_INTERRUPT, &regs, &regs);
    }
}

unsigned int query_largest_dos_free_block(void) {
    union REGS regs;
    /* AH=48h with BX=FFFFh returns the largest available DOS block in paragraphs. */
    regs.h.ah = DOS_GET_LARGEST_FREE_BLOCK;
    regs.w.bx = 0xffff;
    int386(DOS_INTERRUPT, &regs, &regs);
    largest_dos_free_block_bytes = regs.w.bx << 4;
    return largest_dos_free_block_bytes;
}
